$ echo '{ 
    "query": "{
      Get {
        Article {
          title
          url
          wordCount
          inPublication {           
            ... on Publication {    
              name                  
            }
          }
        }
      }
    }"
  }' | curl \
    -X POST \
    -H 'Content-Type: application/json' \
