#include <iostream>

class Polinomio {
private:
  double coeficientes[99];
  int n;

public:
  // Constructor que recibe un array de números reales
  Polinomio(double* coef) {
    this->n = sizeof(coef);
    for (int i = 0; i < n; i++) {
      coeficientes[i] = coef[i];
    }
  }

  // Método que devuelve el grado del polinomio
  int grado() const {
    return n - 1;
  }

  // Método que devuelve el coeficiente ai
  double coeficiente(int i) const {
    return coeficientes[i];
  }

  // Método que evalúa el polinomio para un valor de x
  double valor(double x) {
    double resultado = 0;
    double acumulador = 1;
    for (int i = 0; i < grado(); i++) {
        resultado += coeficientes[i] * acumulador;
        acumulador *= x;
    }
    return resultado;
  }

  // Método que multiplica un polinomio por un número real
  Polinomio multiplicar(double num) {
    double *coef = new double[n];
    for (int i = 0; i < n; i++) {
      coef[i] = coeficientes[i] * num;
    }
    return Polinomio(coef);
  }

  // Método que suma dos polinomios
  Polinomio sumar(const Polinomio &p) {
    double *coef = new double[n];
    for (int i = 0; i < n; i++) {
      coef[i] = coeficiente(i) + p.coeficiente(i);
    }
    return Polinomio(coef);
  }
};

